// ====== CONFIGURAÇÃO DA AUDITORIA (edite só este bloco) ======
const PAINEL_URL   = '__PAINEL_URL__';     // ingest do plugin GLPI (o mesmo do coletor de O.S.)
const PAINEL_TOKEN = '__PAINEL_TOKEN__';
const MSGS_TICKET_MAX = 60;                // últimas N mensagens do atendimento guardadas por auditoria
// auditoria = assunto(s) da O.S. de Auditoria; ativacao = assunto(s) da O.S. de origem (mesmo atendimento)
const BASES = [                            // credencial de cada base fica nos nós "<etapa> <base>"
  { codigo: 'resolutto', nome: 'Resolutto', url: '__URL_RESOLUTTO__', auditoria: [2],  ativacao: [41] },
  { codigo: '4btelecom', nome: '4BTELECOM', url: '__URL_4BTELECOM__', auditoria: [95], ativacao: [16] },
  { codigo: 'ponto',     nome: 'PONTO',     url: '__URL_PONTO__',     auditoria: [54], ativacao: [4]  },
  { codigo: 'cacta',     nome: 'CACTA',     url: '__URL_CACTA__',     auditoria: [12], ativacao: [43] },
  { codigo: 'buzz',      nome: 'BUZZ',      url: '__URL_BUZZ__',      auditoria: [2],  ativacao: [45] },
];
// ============================================================
return [{ json: { PAINEL_URL, PAINEL_TOKEN, MSGS_TICKET_MAX,
  BASES: BASES.map(b => ({ ...b, url: String(b.url || '').trim().replace(/\/+$/, ''),
    auditoria: (b.auditoria || []).map(Number).filter(n => n > 0), ativacao: (b.ativacao || []).map(Number).filter(n => n > 0) })) } }];

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };                 // nada a buscar: consulta vazia (mantém o fluxo)
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpo = (tab, grid, ordem) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
// Etapa 1: O.S. de Auditoria abertas (status diferente de F e C) de cada base.
const cfg = $input.first().json;
return cfg.BASES.map(b => {
  const ok = urlOk(b.url) && b.auditoria.length && b.ativacao.length;
  const grid = [filtroIds('su_oss_chamado.id_assunto', b.auditoria),
    { TB: 'su_oss_chamado.status', OP: '!=', P: 'F' }, { TB: 'su_oss_chamado.status', OP: '!=', P: 'C' }];
  return { json: { base: b.codigo, chave: 'auditorias', url: ok ? b.url + '/webservice/v1/su_oss_chamado' : '',
    corpo: corpo('su_oss_chamado', grid), erro_config: ok ? '' : 'URL ou assuntos (auditoria/ativacao) não preenchidos no Config (' + b.nome + ')' } };
});

const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
  if (typeof raw !== 'string') return raw;
  const txt = raw.replace(/^﻿/, '').trim();
  try { return JSON.parse(txt); } catch (e) { /* tenta limpar */ }
  try { return JSON.parse(txt.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) {
    return { error: 'resposta do IXC não é JSON (' + txt.length + ' bytes): ' + txt.slice(0, 180) };
  }
};
// Devolve {base, chave, resp} (o item pareado em "Buscar auditorias" diz de quem é).
const req = $('Buscar auditorias').item.json;
const resp = req.erro_config ? { error: req.erro_config } : lerIxc($input.item.json || {});
return { json: { base: req.base, chave: req.chave, resp } };

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };                 // nada a buscar: consulta vazia (mantém o fluxo)
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpo = (tab, grid, ordem) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
const falhou = (r) => {
  if (!r) return 'sem resposta';
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + (r.message || JSON.stringify(r)).slice(0, 300);
  if (!Number.isFinite(Number(r.total))) return 'resposta inesperada (sem "total"): ' + JSON.stringify(r).slice(0, 200);
  if (Number(r.total) > 0 && !Array.isArray(r.registros)) return 'IXC informou ' + r.total + ' registros mas não mandou a lista';
  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
// Etapa 2: O.S. de Ativação FINALIZADAS dos clientes das auditorias (id_cliente + assunto "ativacao" + status F)
// e as mensagens dos atendimentos das auditorias.
const cfg = $('Config').first().json;
const resp = {}; for (const it of $input.all()) resp[it.json.base] = it.json.resp;
const out = [];
for (const b of cfg.BASES) {
  const r = resp[b.codigo];
  const erro = falhou(r);
  const tickets = erro ? [] : regs(r).map(o => o.id_ticket);
  const clientes = erro ? [] : regs(r).map(o => o.id_cliente);
  const ok = urlOk(b.url);
  const ctx = { erro, auditorias: erro ? [] : regs(r), total: erro ? null : Number(r.total) };
  const gridAtiv = [filtroIds('su_oss_chamado.id_cliente', clientes), filtroIds('su_oss_chamado.id_assunto', b.ativacao),
    { TB: 'su_oss_chamado.status', OP: '=', P: 'F' }];
  out.push({ json: { base: b.codigo, chave: 'os_cliente', ctx, url: ok ? b.url + '/webservice/v1/su_oss_chamado' : '',
    corpo: corpo('su_oss_chamado', gridAtiv, 'desc'), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
  out.push({ json: { base: b.codigo, chave: 'msgs_ticket', url: ok ? b.url + '/webservice/v1/su_mensagens' : '',
    corpo: corpo('su_mensagens', [filtroIds('su_mensagens.id_ticket', tickets)]), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
  // plano (velocidade) = grupo do LOGIN do cliente (radusuarios.id_grupo -> radgrupos), não o "plano de venda" do contrato
  out.push({ json: { base: b.codigo, chave: 'logins', url: ok ? b.url + '/webservice/v1/radusuarios' : '',
    corpo: corpo('radusuarios', [filtroIds('radusuarios.id_cliente', clientes)]), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
}
return out;

const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
