};
// Devolve {base, chave, resp} (o item pareado em "Buscar atendimentos" diz de quem é).
const req = $('Buscar atendimentos').item.json;
const resp = req.erro_config ? { error: req.erro_config } : lerIxc($input.item.json || {});
return { json: { base: req.base, chave: req.chave, resp } };

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
