  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
const falhou = (r) => {
  if (!r) return 'sem resposta';
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + (r.message || JSON.stringify(r)).slice(0, 300);
