  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
// Etapa 3: escolhe a O.S. de Ativação de cada auditoria e busca mensagens e anexos dela.
// Regra: mesmo CLIENTE, assunto em "ativacao", status F (finalizada); entre várias, a que fechou mais perto (antes)
// da abertura da auditoria; se nenhuma fechou antes, a finalizada mais recente. Vistoria e outras etapas não entram.
const cfg = $('Config').first().json;
const etapa2 = {}; for (const it of $('Buscar atendimentos').all()) if (it.json.chave === 'os_cliente') etapa2[it.json.base] = it.json.ctx;
const resp = {}; for (const it of $input.all()) (resp[it.json.base] = resp[it.json.base] || {})[it.json.chave] = it.json.resp;
const vazio = (d) => !d || String(d).startsWith('0000') ? '' : String(d);
const escolher = (aud, osCli, ativ) => {
  const cand = osCli.filter(o => String(o.id_cliente) === String(aud.id_cliente) && String(o.id) !== String(aud.id)
    && ativ.includes(Number(o.id_assunto)) && String(o.status).toUpperCase() === 'F' && vazio(o.data_fechamento));
  if (!cand.length) return null;
  const ab = vazio(aud.data_abertura);
  const antes = cand.filter(o => vazio(o.data_fechamento) && (!ab || vazio(o.data_fechamento) <= ab));
  if (antes.length) return antes.sort((x, y) => vazio(y.data_fechamento).localeCompare(vazio(x.data_fechamento)) || Number(y.id) - Number(x.id))[0];
  return cand.sort((x, y) => vazio(y.data_fechamento).localeCompare(vazio(x.data_fechamento)) || Number(y.id) - Number(x.id))[0];
};
const out = [];
for (const b of cfg.BASES) {
  const c2 = etapa2[b.codigo] || { erro: 'sem etapa 2', auditorias: [] };
  const r = resp[b.codigo] || {};
  const erro = c2.erro || falhou(r.os_cliente);
  const eHist = erro ? '' : falhou(r.msgs_ticket);   // histórico do atendimento é extra: falha vira aviso, não erro
  const osCli = erro ? [] : regs(r.os_cliente);
  const escolhas = {};
  for (const a of (erro ? [] : c2.auditorias)) {
    const o = Number(a.id_cliente) > 0 ? escolher(a, osCli, b.ativacao) : null;
    escolhas[a.id] = o ? o.id : null;
  }
  const ids = Object.values(escolhas).filter(Boolean);
  const ok = urlOk(b.url);
  const ctx = { erro, total: c2.total, auditorias: erro ? [] : c2.auditorias, escolhas,
    origens: Object.fromEntries(osCli.filter(o => ids.includes(o.id)).map(o => [o.id, o])),
    msgs_ticket: (erro || eHist) ? [] : regs(r.msgs_ticket), aviso: eHist ? 'histórico do atendimento indisponível: ' + eHist : '',
    logins: (erro || falhou(r.logins)) ? [] : regs(r.logins).map(l => ({ id: l.id, id_cliente: l.id_cliente, id_contrato: l.id_contrato, id_grupo: l.id_grupo, login: l.login, ativo: l.ativo })),
    eLogins: erro ? '' : falhou(r.logins) };
  out.push({ json: { base: b.codigo, chave: 'msgs_os', ctx, url: ok ? b.url + '/webservice/v1/su_oss_chamado_mensagem' : '',
    corpo: corpo('su_oss_chamado_mensagem', [filtroIds('su_oss_chamado_mensagem.id_chamado', ids)]), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
  out.push({ json: { base: b.codigo, chave: 'arquivos', url: ok ? b.url + '/webservice/v1/su_oss_chamado_arquivos' : '',
    corpo: corpo('su_oss_chamado_arquivos', [filtroIds('su_oss_chamado_arquivos.id_oss_chamado', ids)]), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
  out.push({ json: { base: b.codigo, chave: 'grupos', url: ok ? b.url + '/webservice/v1/radgrupos' : '',
    corpo: corpo('radgrupos', [filtroIds('radgrupos.id', ctx.logins.map(l => l.id_grupo))]), erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
  // plano contratado: contratos dos clientes das auditorias (falha aqui vira aviso, não derruba a base)
  out.push({ json: { base: b.codigo, chave: 'contratos', url: ok ? b.url + '/webservice/v1/cliente_contrato' : '',
    corpo: corpo('cliente_contrato', [filtroIds('cliente_contrato.id_cliente', (erro ? [] : c2.auditorias).map(a => a.id_cliente))]),
    erro_config: ok ? '' : 'URL não preenchida (' + b.nome + ')' } });
}
return out;

const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
