  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
// Monta um retrato por base para o painel. Falha em qualquer etapa = {base, tipo, erro} (o painel não encerra nada).
const cfg = $('Config').first().json;
const etapa3 = {}; for (const it of $('Buscar ativações').all()) if (it.json.chave === 'msgs_os') etapa3[it.json.base] = it.json.ctx;
const resp = {}; for (const it of $input.all()) (resp[it.json.base] = resp[it.json.base] || {})[it.json.chave] = it.json.resp;
const corta = (s, n) => String(s == null ? '' : s).slice(0, n || 4000);
const pega = (o, campos) => { const x = {}; for (const k of campos) if (o[k] !== undefined) x[k] = (k === 'mensagem' || k === 'mensagem_resposta' || k === 'historico') ? corta(o[k]) : o[k]; return x; };
const out = [];
for (const b of cfg.BASES) {
  const c = etapa3[b.codigo] || { erro: 'sem etapa 3', auditorias: [] };
  const r = resp[b.codigo] || {};
  let erro = c.erro;
  if (!erro) { const e = falhou(r.msgs_os); if (e) erro = 'mensagens da O.S. de Ativação: ' + e; }
  if (!erro) { const e = falhou(r.arquivos); if (e) erro = 'anexos da O.S. de Ativação: ' + e; }
  if (erro) { out.push({ json: { base: b.codigo, tipo: 'auditorias', erro: corta('Auditoria: ' + erro, 900) } }); continue; }
  const msgsOs = {}, arqs = {}, hist = {};
  for (const m of regs(r.msgs_os)) (msgsOs[m.id_chamado] = msgsOs[m.id_chamado] || []).push(pega(m, ['id', 'data', 'status', 'id_evento', 'id_tecnico', 'mensagem', 'historico']));
  for (const f of regs(r.arquivos)) (arqs[f.id_oss_chamado] = arqs[f.id_oss_chamado] || []).push(pega(f, ['id', 'descricao', 'nome_arquivo', 'data_envio']));
  for (const m of c.msgs_ticket) (hist[m.id_ticket] = hist[m.id_ticket] || []).push(pega(m, ['id', 'data', 'mensagem']));
  // plano contratado = grupo (velocidade) do LOGIN do cliente — campo "Plano" do cadastro do login (radusuarios.id_grupo -> radgrupos).
  // Escolha do login: o da própria O.S. (id_login); senão o do contrato da O.S.; senão os logins ativos do cliente.
  // Sem login: cai no nome do contrato (cliente_contrato.contrato = plano de venda).
  const eCont = falhou(r.contratos), eGrp = falhou(r.grupos);
  const contratos = eCont ? [] : regs(r.contratos);
  const grupos = {}; for (const g of (eGrp ? [] : regs(r.grupos))) grupos[String(g.id)] = String(g.grupo || g.descricao || g.nome || '').trim();
  const logins = c.logins || [];
  const num = (v) => Number(v || 0);
  const idCont = (o) => o ? num(o.id_contrato_kit || o.id_contrato) : 0;
  const nomeContrato = (k) => String(k.contrato || k.descricao_aux_plano_venda || 'Contrato #' + k.id).trim();
  const nomeGrupo = (l) => grupos[String(l.id_grupo)] || (num(l.id_grupo) > 0 ? 'Plano #' + l.id_grupo : '');
  const plano = (a, o) => {
    const lCli = logins.filter(l => String(l.id_cliente) === String(a.id_cliente));
    const kCli = contratos.filter(k => String(k.id_cliente) === String(a.id_cliente));
    const idL = num(a.id_login) || num(o && o.id_login), idK = idCont(a) || idCont(o);
    let ls = idL ? lCli.filter(l => num(l.id) === idL) : [];
    if (!ls.length && idK) ls = lCli.filter(l => num(l.id_contrato) === idK);
    if (!ls.length) { const at = lCli.filter(l => String(l.ativo).toUpperCase() !== 'N'); ls = at.length ? at : lCli; }
    ls = ls.filter(l => nomeGrupo(l));
    if (ls.length) {
      const nomes = [...new Set(ls.map(nomeGrupo))];
      const k = contratos.find(x => num(x.id) === num(ls[0].id_contrato));
      return { nome: nomes.join(' | '), contrato_id: ls.length === 1 ? (num(ls[0].id_contrato) || null) : null, status: k ? String(k.status || '') : '', varios: nomes.length > 1 ? nomes.length : 0,
        login: ls.length === 1 ? String(ls[0].login || '') : '', contrato: k ? nomeContrato(k) : '' };
    }
    // sem login com plano: nome do contrato
    let k = idK ? kCli.find(x => num(x.id) === idK) : null;
    if (!k) { const at = kCli.filter(x => String(x.status).toUpperCase() === 'A'); if (at.length === 1) k = at[0];
      else if (at.length > 1) return { nome: at.map(nomeContrato).join(' | '), contrato_id: null, status: 'A', varios: at.length, login: '', contrato: '' }; }
    return k ? { nome: nomeContrato(k), contrato_id: num(k.id), status: String(k.status || ''), varios: 0, login: '', contrato: '' } : null;
  };
  const max = Number(cfg.MSGS_TICKET_MAX) || 60;
  const auditorias = c.auditorias.map(a => {
    const idO = c.escolhas[a.id];
    const o = idO ? c.origens[idO] : null;
    const h = (hist[a.id_ticket] || []).sort((x, y) => Number(x.id) - Number(y.id)).slice(-max);
    return { ...pega(a, ['id', 'protocolo', 'status', 'id_assunto', 'id_ticket', 'id_cliente', 'id_tecnico', 'setor', 'data_abertura', 'mensagem']),
      origem: o ? pega(o, ['id', 'protocolo', 'status', 'id_assunto', 'id_ticket', 'id_tecnico', 'data_abertura', 'data_fechamento', 'mensagem', 'mensagem_resposta']) : null,
      msgs_os: o ? (msgsOs[o.id] || []) : [], arquivos: o ? (arqs[o.id] || []) : [], msgs_ticket: h, plano: plano(a, o) };
  });
  const semOrigem = auditorias.filter(a => !a.origem).map(a => a.id);
  out.push({ json: { base: b.codigo, tipo: 'auditorias', ixc_url: b.url, total: c.total, auditorias,
    avisos: [c.aviso, c.eLogins ? 'logins (plano) indisponíveis: ' + c.eLogins : '', eGrp ? 'planos (radgrupos) indisponíveis: ' + eGrp : '', eCont ? 'contratos indisponíveis: ' + eCont : '', semOrigem.length ? 'sem Ativação de origem: O.S. ' + semOrigem.slice(0, 10).join(', ') : ''].filter(Boolean) } });
}
return out;
